 public static void InstallAtmosphere(TerrierMatch m){if(m.volcano==null)return;foreach(var camera in m.cabViews){camera.view.GetUniversalAdditionalCameraData().requiresColorTexture=true;EditorUtility.SetDirty(camera.view.GetUniversalAdditionalCameraData());}m.broadcast.view.GetUniversalAdditionalCameraData().requiresColorTexture=true;EditorUtility.SetDirty(m.broadcast.view.GetUniversalAdditionalCameraData());if(m.volcano.transform.Find("Bounded heat haze and drifting embers")!=null)return;
  var root=new GameObject("Bounded heat haze and drifting embers").transform;root.SetParent(m.volcano.transform,false);var hazeMaterial=AssetDatabase.LoadAssetAtPath<Material>(Root+"Refractive volcanic heat.mat");if(hazeMaterial==null){hazeMaterial=new Material(AssetDatabase.LoadAssetAtPath<Material>(Root+"Soft volcanic smoke.mat"));AssetDatabase.CreateAsset(hazeMaterial,Root+"Refractive volcanic heat.mat");}hazeMaterial.name="Refractive volcanic heat";hazeMaterial.SetColor("_BaseColor",Color.white);hazeMaterial.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/WeatherMaker/Prefab/Textures/Water/WeatherMakerWaterBump.png"));hazeMaterial.SetFloat("_DistortionEnabled",1);hazeMaterial.SetFloat("_DistortionStrength",.4f);hazeMaterial.SetFloat("_DistortionStrengthScaled",.04f);hazeMaterial.SetFloat("_DistortionBlend",1);hazeMaterial.SetFloat("_FlipbookBlending",0);hazeMaterial.SetFloat("_SoftParticlesEnabled",0);hazeMaterial.SetFloat("_CameraFadingEnabled",0);hazeMaterial.DisableKeyword("_FLIPBOOKBLENDING_ON");hazeMaterial.DisableKeyword("_SOFTPARTICLES_ON");hazeMaterial.DisableKeyword("_FADING_ON");hazeMaterial.EnableKeyword("_DISTORTION_ON");hazeMaterial.EnableKeyword("_NORMALMAP");EditorUtility.SetDirty(hazeMaterial);var flare=AssetDatabase.LoadAssetAtPath<Material>(Root+"Transparent comic flare.mat");
  for(int i=0;i<6;i++){var vent=m.volcano.transform.Find("Volcanic vent smoke "+i).GetComponent<ParticleSystem>();var haze=UnityEngine.Object.Instantiate(vent,root);haze.name="Refractive heat plume "+i;haze.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);haze.transform.position=vent.transform.position+Vector3.up*4;var hm=haze.main;hm.startLifetime=new ParticleSystem.MinMaxCurve(4,7);hm.startSize=new ParticleSystem.MinMaxCurve(18,35);hm.startSpeed=new ParticleSystem.MinMaxCurve(2,4);hm.startColor=new Color(1,1,1,.38f);hm.maxParticles=32;var he=haze.emission;he.rateOverTime=1.5f;var hr=haze.GetComponent<ParticleSystemRenderer>();hr.sharedMaterial=hazeMaterial;hr.SetActiveVertexStreams(new List<ParticleSystemVertexStream>{ParticleSystemVertexStream.Position,ParticleSystemVertexStream.Normal,ParticleSystemVertexStream.Tangent,ParticleSystemVertexStream.Color,ParticleSystemVertexStream.UV});var hs=haze.sizeOverLifetime;hs.enabled=true;hs.size=new ParticleSystem.MinMaxCurve(1,AnimationCurve.Linear(0,.7f,1,1.2f));var hc=haze.colorOverLifetime;hc.enabled=true;var fade=new Gradient();fade.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(Color.white,1)},new[]{new GradientAlphaKey(0,0),new GradientAlphaKey(1,.25f),new GradientAlphaKey(0,1)});hc.color=fade;
   var sparks=new GameObject("Drifting molten embers "+i).AddComponent<ParticleSystem>();sparks.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);sparks.transform.SetParent(root,false);sparks.transform.SetPositionAndRotation(vent.transform.position+Vector3.up*3,Quaternion.Euler(-90,0,0));var main=sparks.main;main.loop=true;main.playOnAwake=true;main.duration=6;main.startLifetime=new ParticleSystem.MinMaxCurve(5,10);main.startSpeed=new ParticleSystem.MinMaxCurve(3,9);main.startSize=new ParticleSystem.MinMaxCurve(.15f,.45f);main.startColor=new ParticleSystem.MinMaxGradient(new Color(2.5f,.18f,.015f),new Color(3,1,.035f));main.maxParticles=96;main.simulationSpace=ParticleSystemSimulationSpace.World;main.gravityModifier=.06f;var shape=sparks.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.radius=18;shape.angle=18;var emission=sparks.emission;emission.rateOverTime=4;var noise=sparks.noise;noise.enabled=true;noise.strength=1.2f;noise.frequency=.15f;var over=sparks.colorOverLifetime;over.enabled=true;var gradient=new Gradient();gradient.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(new Color(1,.12f,.01f),1)},new[]{new GradientAlphaKey(0,0),new GradientAlphaKey(.9f,.15f),new GradientAlphaKey(0,1)});over.color=gradient;var renderer=sparks.GetComponent<ParticleSystemRenderer>();renderer.sharedMaterial=flare;renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;
