 public static void ValidateAtmosphere(TerrierMatch m){if(m.volcano==null)throw new Exception("Terrier volcanic world missing");var root=m.volcano.transform.Find("Bounded heat haze and drifting embers");if(root==null||root.GetComponentsInChildren<ParticleSystem>(true).Length!=12)throw new Exception("Six bounded heat/ember pairs required");for(int i=0;i<6;i++){var haze=root.Find("Refractive heat plume "+i).GetComponent<ParticleSystem>();var embers=root.Find("Drifting molten embers "+i).GetComponent<ParticleSystem>();var material=haze.GetComponent<ParticleSystemRenderer>().sharedMaterial;if(haze.main.maxParticles!=32||embers.main.maxParticles!=96||!material.IsKeywordEnabled("_DISTORTION_ON")||!material.IsKeywordEnabled("_NORMALMAP")||material.GetTexture("_BumpMap")==null)throw new Exception("Terrier bounded vendor-particle heat/ember settings invalid");}foreach(var camera in m.cabViews)if(!camera.view.GetUniversalAdditionalCameraData().requiresColorTexture)throw new Exception("Terrier cab heat requires its own scene color copy");if(!m.broadcast.view.GetUniversalAdditionalCameraData().requiresColorTexture)throw new Exception("Terrier broadcast heat requires its own scene color copy");}
 public static void InstallSupports(TerrierMatch m){if(m.volcano==null||m.volcano.transform.Find("Installed scaffold bridge pylons")!=null)return;const string path=Root+"Installed scaffold bridge pylon.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/ScaffoldsPack/Mesh/SM_StairTowerMid.fbx");if(source==null)throw new Exception("Installed ScaffoldsPack middle tower model required");var part=source.GetComponentInChildren<MeshFilter>(true).sharedMesh;var bounds=part.bounds;const int sections=20;const float scale=2.5f;var combine=new CombineInstance[sections*part.subMeshCount];for(int i=0;i<sections;i++)for(int sub=0;sub<part.subMeshCount;sub++)combine[i*part.subMeshCount+sub]=new CombineInstance{mesh=part,subMeshIndex=sub,transform=Matrix4x4.TRS(new Vector3(-bounds.center.x*scale,(i*bounds.size.y-bounds.min.y)*scale,-bounds.center.z*scale),Quaternion.identity,Vector3.one*scale)};mesh=new Mesh{name="Installed scaffold model repeated into bridge pylon",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.CombineMeshes(combine,true,true);var vertices=mesh.vertices;float height=sections*bounds.size.y*scale;for(int i=0;i<vertices.Length;i++)vertices[i].y/=height;mesh.vertices=vertices;mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);}
  var root=new GameObject("Installed scaffold bridge pylons").transform;root.SetParent(m.volcano.transform,false);var material=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckBungeeDemolition/Materials/Industrial crane enamel.mat");for(int at=0;at<3;at++)for(int side=-1;side<=1;side+=2){float z=25+at*50;var top=m.course.World(new Vector3(side*(m.course.HalfWidth(z)-5),-.65f,z));float ground=m.volcano.terrain.SampleHeight(top)+m.volcano.terrain.transform.position.y;float height=top.y-ground;var pylon=new GameObject("Actual scaffold bridge support "+at+" / "+side);pylon.transform.SetParent(root,false);pylon.transform.SetPositionAndRotation(new Vector3(top.x,ground,top.z),m.course.Heading);pylon.transform.localScale=new Vector3(1,height,1);pylon.AddComponent<MeshFilter>().sharedMesh=mesh;pylon.AddComponent<MeshRenderer>().sharedMaterial=material;var collider=pylon.AddComponent<BoxCollider>();collider.center=new Vector3(0,.5f,0);collider.size=new Vector3(mesh.bounds.size.x,1,mesh.bounds.size.z);pylon.isStatic=true;}EditorUtility.SetDirty(m.volcano);
 } public static float Height(float x,float z){float r=new Vector2(x,z).magnitude;float angle=Mathf.Atan2(z,x);float ridges=Mathf.PerlinNoise(x*.006f+14,z*.006f+9);if(r<340)return -153+18*r*r/(340*340);if(r<510)return Mathf.Lerp(-135,-8,Mathf.SmoothStep(0,1,(r-340)/170))+(ridges-.5f)*14*Mathf.Sin((r-340)/170*Mathf.PI);float mountains=Mathf.Exp(-Mathf.Pow((r-730)/230,2))*(85+85*ridges+45*Mathf.Sin(angle*7)*Mathf.Sin(angle*7));return -8+mountains*Mathf.SmoothStep(0,1,(r-510)/90)+(ridges-.5f)*18*Mathf.SmoothStep(0,1,(r-510)/90);}
 static Mesh Disc(){const string path=Root+"Molten lake disc.asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old!=null)return old;var vertices=new Vector3[130];var triangles=new int[128*3];for(int i=0;i<=128;i++){float a=i*Mathf.PI*2/128;vertices[i+1]=new Vector3(Mathf.Cos(a)*340,0,Mathf.Sin(a)*340);if(i<128){triangles[i*3]=0;triangles[i*3+1]=i+2;triangles[i*3+2]=i+1;}}var mesh=new Mesh{name="Physical volcano molten lake"};mesh.vertices=vertices;mesh.triangles=triangles;mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);return mesh;}
